"""
GAKTransformerPredictor v9.5 — MLP-предиктор для суррогатного моделирования.
Архитектура: 5 -> 128 -> 128 -> 64 -> 4 (ReLU), backprop, z-score нормализация.

v9.5: DeepSeek review final — fix regression in load() factory-norms,
      remove unused config from _compute_error, update comment.
v9.4: cosmetics from DeepSeek review — заголовок, hasattr упрощён, pre_forecast при n=1.
v9.3: backprop fix (linear weighting), factory predict, pre_forecast на старых нормах,
      LR decay 1e-4, _is_valid_experience через _denorm_value, _extract_targets merged,
      factory-нормы <50, _compute_error DRY, _error_history 50.
v9.2: расширен клип денормализации ratio с [-10, 1] до [-10, 3] (потолок 1000 вместо 10).
v9.1: расширен клип денормализации ratio с [-10, 1] до [-10, 3] (потолок 1000 вместо 10).
v9: откат к v7 + мусорный фильтр (T < 1e6, pair_rate < 1). Вес ratio x2, 40 эпох,
    LR decay 1e-6, простой случайный батч (без стратификации).
v8: фильтр мусорных точек + вес ratio x5 + стратификация (СЛОМАНО — ratio=10 везде).
v7: расширенная архитектура (128-128-64), 40 эпох, батч 128, клип ratio [-10, 1].
"""

import numpy as np
import json
import os
import zlib
import base64

_DEFAULT_MODEL_B64 = ""

class GAKTransformerPredictor:
    """MLP-based surrogate model for GAK-WaveCAD."""

    def __init__(self, config=None):
        cfg = config or {}
        self.n_features = int(cfg.get("n_features", 5))
        self.n_targets = int(cfg.get("n_targets", 4))
        self.hidden1 = int(cfg.get("hidden1", 128))
        self.hidden2 = int(cfg.get("hidden2", 128))
        self.hidden3 = int(cfg.get("hidden3", 64))
        self.lr = float(cfg.get("lr", 1e-3))
        self.max_grad_norm = 10.0

        # Нормализация: log_plus для больших величин, log_raw для ratio
        self._log_plus_names = ("T_plasma", "P_gas", "pair_rate", "density", "E_field")
        self._log_raw_names = ("ratio",)
        self._log_names = self._log_plus_names + self._log_raw_names
        self._target_names = ["T_plasma", "P_gas", "pair_rate", "ratio"]
        self._feature_names = ["T_plasma", "n_density", "pl_radius", "E_field", "external_B"]

        # Вес ratio в loss (x2)
        self._target_weights = np.array([1.0, 1.0, 1.0, 2.0], dtype=np.float64)

        self.rng = np.random.default_rng(42)
        scale = 0.03

        # Слои: 5 -> 128 -> 128 -> 64 -> 4
        self.W1 = self.rng.standard_normal((self.n_features, self.hidden1)) * scale
        self.b1 = np.zeros(self.hidden1)
        self.W2 = self.rng.standard_normal((self.hidden1, self.hidden2)) * scale
        self.b2 = np.zeros(self.hidden2)
        self.W3 = self.rng.standard_normal((self.hidden2, self.hidden3)) * scale
        self.b3 = np.zeros(self.hidden3)
        self.W4 = self.rng.standard_normal((self.hidden3, self.n_targets)) * scale
        self.b4 = np.zeros(self.n_targets)

        # Нормализация (z-score)
        self.feature_mean = np.zeros(self.n_features)
        self.feature_std = np.ones(self.n_features)
        self.target_mean = np.zeros(self.n_targets)
        self.target_std = np.ones(self.n_targets)

        # Опыт
        self.experience_configs = []
        self.experience_targets = []
        self.is_trained = False
        self.n_experiences = 0
        self.n_predictions = 0
        self.last_error_pct = 100.0
        self.last_error_linear_pct = 0.0
        self.last_forecast = None
        self._error_history = []

        self._train_steps = 0

        # v9.3: Factory-нормализация (для защиты при < 50 опытах)
        self._factory_feature_mean = None
        self._factory_feature_std = None
        self._factory_target_mean = None
        self._factory_target_std = None

        # v9.6: Счётчики для диагностики фильтра и норм
        self._n_accepted = 0
        self._n_rejected = 0
        self._n_rejected_no_targets = 0
        self._norms_switched = False
        self._filter_auto_disabled = False
        self._filter_eval_count = 0

    # --- Алиасы для совместимости с оптимизатором и страницами ---

    @property
    def n_train(self):
        return self.n_experiences

    @property
    def _last_error(self):
        return self.last_error_pct

    @property
    def error_history(self):
        return self._error_history

    # --- Нормализация значений ---

    def _norm_value(self, val, name):
        if name in self._log_plus_names:
            return float(np.log10(abs(val) + 1.0))
        if name in self._log_raw_names:
            return float(np.log10(max(abs(val), 1e-30)))
        return float(val)

    def _denorm_value(self, val, name):
        if name in self._log_plus_names:
            val = float(np.clip(val, -20, 20))
            return float(10.0 ** val - 1.0)
        if name in self._log_raw_names:
            val = float(np.clip(val, -10, 3))
            return float(10.0 ** val)
        return float(val)

    # --- Forward pass ---

    def _forward(self, x):
        z1 = x @ self.W1 + self.b1
        a1 = np.maximum(0, z1)
        z2 = a1 @ self.W2 + self.b2
        a2 = np.maximum(0, z2)
        z3 = a2 @ self.W3 + self.b3
        a3 = np.maximum(0, z3)
        out = a3 @ self.W4 + self.b4
        cache = (x, z1, a1, z2, a2, z3, a3, out)
        return out, cache

    def _backward(self, dout, cache):
        x, z1, a1, z2, a2, z3, a3, out = cache
        dW4 = a3[:, None] @ dout[None, :]
        db4 = dout
        da3 = self.W4 @ dout
        dz3 = da3 * (z3 > 0)
        dW3 = a2[:, None] @ dz3[None, :]
        db3 = dz3
        da2 = self.W3 @ dz3
        dz2 = da2 * (z2 > 0)
        dW2 = a1[:, None] @ dz2[None, :]
        db2 = dz2
        da1 = self.W2 @ dz2
        dz1 = da1 * (z1 > 0)
        dW1 = x[:, None] @ dz1[None, :]
        db1 = dz1
        return {"W1": dW1, "b1": db1, "W2": dW2, "b2": db2,
                "W3": dW3, "b3": db3, "W4": dW4, "b4": db4}

    def _clip_grads(self, grads):
        total_norm = 0.0
        for k in grads:
            total_norm += np.sum(grads[k] ** 2)
        total_norm = np.sqrt(total_norm)
        if total_norm > self.max_grad_norm and total_norm > 0:
            scale = self.max_grad_norm / total_norm
            for k in grads:
                grads[k] *= scale

    def _train_step(self, x_norm, y_norm):
        pred, cache = self._forward(x_norm)
        diff = pred - y_norm
        # v9.3: Линейное взвешивание — ratio вес x2, не x4
        weighted_diff = diff * self._target_weights
        loss = float(np.mean(self._target_weights * diff ** 2))
        dout = 2.0 * weighted_diff / self.n_targets
        grads = self._backward(dout, cache)
        self._clip_grads(grads)
        # v9.3: LR decay 1e-4 — реальный, не 1e-6 (множитель 1.5 за 5000 шагов)
        lr_eff = self.lr / (1.0 + self._train_steps * 1e-4)
        self._train_steps += 1
        for k in ["W1", "b1", "W2", "b2", "W3", "b3", "W4", "b4"]:
            setattr(self, k, getattr(self, k) - lr_eff * grads[k])
        return loss

    # --- Feature extraction ---

    def _extract_features(self, config):
        pm = config.get("plasma_monitor", config)
        qv = config.get("quantum_vacuum", {})
        T = self._norm_value(float(pm.get("temperature", 5e6)), "T_plasma")
        n = self._norm_value(float(pm.get("density_number", 1e20)), "density")
        R = float(pm.get("radius", 0.01)) * 1000
        E = self._norm_value(float(qv.get("E_field", 0)), "E_field")
        B = float(pm.get("external_B", 30.0))
        return np.array([T, n, R, E, B], dtype=np.float64)

    def _extract_targets_from_dict(self, targets_dict):
        vec = np.zeros(self.n_targets, dtype=np.float64)
        for i, name in enumerate(self._target_names):
            val = float(targets_dict.get(name, 0.0))
            vec[i] = self._norm_value(val, name)
        return vec

    def _extract_targets(self, history):
        # v9.3: объединённые ветки
        if "step" not in history or not history.get("step"):
            return self._extract_targets_from_dict(history)
        vec = np.zeros(self.n_targets, dtype=np.float64)
        for i, name in enumerate(self._target_names):
            vals = history.get(name, [])
            if len(vals) == 0:
                vec[i] = self._norm_value(0.0, name)
            else:
                vec[i] = self._norm_value(float(vals[-1]), name)
        return vec

    # --- Predict / Eval ---

    def _eval_forecast(self, config):
        # v9.3: убран n_experiences < 1 — factory-модель предсказывает сразу
        if not self.is_trained:
            return None
        cv = self._extract_features(config)
        cv_norm = (cv - self.feature_mean) / self.feature_std
        out, _ = self._forward(cv_norm)
        forecast = {}
        for i, name in enumerate(self._target_names):
            val_std = float(out[i]) * self.target_std[i] + self.target_mean[i]
            forecast[name] = self._denorm_value(val_std, name)
        return forecast

    def predict(self, config):
        forecast = self._eval_forecast(config)
        if forecast is None:
            self.last_forecast = None
            return None
        self.last_forecast = forecast
        self.n_predictions += 1
        return forecast

    def predict_evolution(self, config):
        return self.predict(config)

    # --- Self-learn ---

    def _is_valid_experience(self, targets):
        """Фильтр мусорных точек: T_plasma < 1e6 или pair_rate < 1."""
        # v9.6: если фильтр автоотключён — пропускаем все точки
        if self._filter_auto_disabled:
            return True
        # v9.3: используем _denorm_value вместо дублирования логики
        T_raw = self._denorm_value(targets[0], "T_plasma")
        if T_raw < 1e6:
            return False
        pr_raw = self._denorm_value(targets[2], "pair_rate")
        if pr_raw < 1.0:
            return False
        return True

    def add_experience(self, config, history):
        """Только добавляет опыт в буфер. Без обучения.
        Возвращает True если точка валидна и добавлена."""
        targets = self._extract_targets(history)
        if targets is None:
            self._n_rejected_no_targets += 1
            return False
        cv = self._extract_features(config)
        if not self._is_valid_experience(targets):
            self._n_rejected += 1
            self._filter_eval_count += 1
            # v9.6: автоотключение фильтра при rejected_ratio > 0.5 на первых 20 точках
            if (not self._filter_auto_disabled and
                    self._filter_eval_count >= 20 and
                    self._n_rejected > self._filter_eval_count * 0.5):
                self._filter_auto_disabled = True
                print(f"[AutoLearn] Filter auto-disabled: rejected {self._n_rejected}/"
                      f"{self._filter_eval_count} in first {self._filter_eval_count} points")
            return False
        self._n_accepted += 1
        self.experience_configs.append(cv.copy())
        self.experience_targets.append(targets.copy())
        self.n_experiences += 1
        return True

    def _compute_error(self, pre_forecast, history):
        """Вычисление ошибки предсказания ДО обучения (log и linear)."""
        errs = []
        for i, name in enumerate(self._target_names):
            actual_raw = (float(history.get(name, 0.0)) if "step" not in history
                          else float(history[name][-1]) if history.get(name) else 0.0)
            actual_log = self._norm_value(actual_raw, name)
            pred_log = self._norm_value(pre_forecast[name], name)
            diff = abs(pred_log - actual_log)
            errs.append(min(diff * 50.0, 100.0))
        self._error_history.append(float(np.mean(errs)))
        # v9.3: 50 вместо 10 — больше данных для тренда
        if len(self._error_history) > 50:
            self._error_history = self._error_history[-50:]
        self.last_error_pct = float(np.mean(self._error_history))
        errs_lin = []
        for i, name in enumerate(self._target_names):
            actual_val = (float(history[name]) if "step" not in history
                         else float(history[name][-1]) if history.get(name) else 0.0)
            pred_val = pre_forecast[name]
            if abs(actual_val) > 1e-10:
                errs_lin.append(abs(pred_val - actual_val) / abs(actual_val) * 100.0)
        if errs_lin:
            self.last_error_linear_pct = float(np.mean(errs_lin))

    def train(self, config=None, history=None):
        """Только обучение по накопленному опыту.
        config/history — опционально, для оценки ошибки ДО обучения."""
        # v9.4: pre_forecast ДО early-return — меряем ошибку с первой точки
        if config is not None and history is not None and self.is_trained:
            pre_forecast = self._eval_forecast(config)
            if pre_forecast is not None:
                self._compute_error(pre_forecast, history)

        if self.n_experiences < 2:
            return 0.0

        # v9.3: pre_forecast на старых нормах — меряем ДО пересчёта
        # (уже сделано выше)

        # v9.3: Не перезаписываем factory-нормы при < 50 опытах
        # v9.6: детект смены норм + сброс LR + доп. эпохи
        norm_switched = False
        if self.n_experiences >= 50 or self._factory_feature_mean is None:
            if not self._norms_switched and self.n_experiences >= 50:
                self._norms_switched = True
                norm_switched = True
                self._train_steps = 0  # v9.6: LR reset
                print(f"[AutoLearn] Norm switch at exp={self.n_experiences} — extra retraining")
            all_c = np.array(self.experience_configs)
            self.feature_mean = np.mean(all_c, axis=0)
            self.feature_std = np.maximum(np.std(all_c, axis=0), 0.01)
            all_t = np.array(self.experience_targets)
            self.target_mean = np.mean(all_t, axis=0)
            self.target_std = np.maximum(np.std(all_t, axis=0), 0.01)

        # Простой случайный батч (без стратификации)
        n_batch = min(128, self.n_experiences)
        n_epochs = 80 if norm_switched else 40
        total_loss = 0.0
        total_steps = 0

        for _ in range(n_epochs):
            batch_idx = self.rng.choice(self.n_experiences, size=n_batch, replace=True)
            self.rng.shuffle(batch_idx)
            for idx in batch_idx:
                bc = self.experience_configs[idx]
                bt = self.experience_targets[idx]
                bc_norm = (bc - self.feature_mean) / self.feature_std
                bt_norm = (bt - self.target_mean) / self.target_std
                total_loss += self._train_step(bc_norm, bt_norm)
                total_steps += 1

        self.is_trained = True
        return total_loss / max(total_steps, 1)

    def self_learn(self, config, history):
        """Полный цикл: добавить опыт + обучить. Для обратной совместимости."""
        ok = self.add_experience(config, history)
        # v9.6: логирование каждые 10 отбраковок
        if self._n_rejected > 0 and self._n_rejected % 10 == 0 and self._n_accepted == 0:
            print(f"[AutoLearn] exp stats: accepted={self._n_accepted}, "
                  f"rejected(filter)={self._n_rejected}, "
                  f"rejected(no_targets)={self._n_rejected_no_targets}, "
                  f"n_exp={self.n_experiences}")
        return self.train(config, history)

    # --- Reset ---

    def reset(self):
        cfg = {
            'n_features': self.n_features, 'n_targets': self.n_targets,
            'hidden1': self.hidden1, 'hidden2': self.hidden2, 'hidden3': self.hidden3,
            'lr': self.lr,
        }
        self.__init__(cfg)

    def _validate_shapes(self):
        """v9.6: Проверка консистентности форм весов после загрузки."""
        expected = {
            'W1': (self.n_features, self.hidden1),
            'b1': (self.hidden1,),
            'W2': (self.hidden1, self.hidden2),
            'b2': (self.hidden2,),
            'W3': (self.hidden2, self.hidden3),
            'b3': (self.hidden3,),
            'W4': (self.hidden3, self.n_targets),
            'b4': (self.n_targets,),
        }
        for name, exp_shape in expected.items():
            val = getattr(self, name, None)
            if val is None or not hasattr(val, 'shape'):
                return False
            if val.shape != exp_shape:
                print(f"[AI] Shape mismatch: {name} expected {exp_shape}, got {val.shape}")
                return False
        return True

    @property
    def _has_runtime_experience(self):
        """v9.6: Отличает 'веса загружены' от 'есть runtime-опыт'."""
        return self.n_experiences > 0

    # --- Save / Load ---

    def save(self, path):
        data = {
            '_model_type': 'MLP',
            '_model_version': 9,
            'n_features': self.n_features, 'n_targets': self.n_targets,
            'hidden1': self.hidden1, 'hidden2': self.hidden2, 'hidden3': self.hidden3,
            'lr': self.lr, 'max_grad_norm': self.max_grad_norm,
            'W1': self.W1.tolist(), 'b1': self.b1.tolist(),
            'W2': self.W2.tolist(), 'b2': self.b2.tolist(),
            'W3': self.W3.tolist(), 'b3': self.b3.tolist(),
            'W4': self.W4.tolist(), 'b4': self.b4.tolist(),
            'feature_mean': self.feature_mean.tolist(),
            'feature_std': self.feature_std.tolist(),
            'target_mean': self.target_mean.tolist(),
            'target_std': self.target_std.tolist(),
            'is_trained': self.is_trained, 'n_experiences': self.n_experiences,
            'n_predictions': self.n_predictions,
            'last_error_pct': self.last_error_pct,
            'last_error_linear_pct': self.last_error_linear_pct,
            '_error_history': self._error_history,
            '_train_steps': self._train_steps,
            'experience_configs': [c.tolist() for c in self.experience_configs],
            'experience_targets': [t.tolist() for t in self.experience_targets],
            # v9.3: сохраняем factory-нормы
            '_factory_feature_mean': self._factory_feature_mean.tolist() if self._factory_feature_mean is not None else None,
            '_factory_feature_std': self._factory_feature_std.tolist() if self._factory_feature_std is not None else None,
            '_factory_target_mean': self._factory_target_mean.tolist() if self._factory_target_mean is not None else None,
            '_factory_target_std': self._factory_target_std.tolist() if self._factory_target_std is not None else None,
            # v9.6: счётчики и флаги
            '_n_accepted': self._n_accepted,
            '_n_rejected': self._n_rejected,
            '_n_rejected_no_targets': self._n_rejected_no_targets,
            '_norms_switched': self._norms_switched,
            '_filter_auto_disabled': self._filter_auto_disabled,
            '_filter_eval_count': self._filter_eval_count,
        }
        with open(path, 'w') as f:
            json.dump(data, f)

    def load(self, path):
        """v9.6: Загрузка с реинициализацией архитектуры из JSON + валидация форм."""
        if not os.path.exists(path):
            return False
        try:
            with open(path, 'r') as f:
                data = json.load(f)
        except Exception as e:
            print(f"[AI] Load failed (JSON parse): {e}")
            return False
        if data.get('_model_type') != 'MLP':
            return False
        # v9.6: реинициализация модели с архитектурой из JSON ДО загрузки весов
        cfg = {
            'n_features': int(data.get('n_features', 5)),
            'n_targets': int(data.get('n_targets', 4)),
            'hidden1': int(data.get('hidden1', 128)),
            'hidden2': int(data.get('hidden2', 128)),
            'hidden3': int(data.get('hidden3', 64)),
            'lr': float(data.get('lr', 1e-3)),
        }
        self.__init__(cfg)
        # Загрузка скалярных полей
        for attr in ['is_trained', 'n_experiences', 'n_predictions',
                      'last_error_pct', 'last_error_linear_pct', '_train_steps']:
            if attr in data:
                setattr(self, attr, data[attr])
        self._error_history = data.get('_error_history', [])
        # Загрузка весов с проверкой наличия ключей
        for attr in ['W1', 'b1', 'W2', 'b2', 'W3', 'b3', 'W4', 'b4',
                      'feature_mean', 'feature_std', 'target_mean', 'target_std']:
            if attr in data:
                setattr(self, attr, np.array(data[attr]))
        # v9.6: валидация форм после загрузки
        if not self._validate_shapes():
            print(f"[AI] Load failed: weight shape mismatch after load")
            return False
        self.experience_configs = [np.array(c) for c in data.get('experience_configs', [])]
        self.experience_targets = [np.array(t) for t in data.get('experience_targets', [])]
        # v9.6: загрузка счётчиков
        self._n_accepted = data.get('_n_accepted', 0)
        self._n_rejected = data.get('_n_rejected', 0)
        self._n_rejected_no_targets = data.get('_n_rejected_no_targets', 0)
        self._norms_switched = data.get('_norms_switched', False)
        self._filter_auto_disabled = data.get('_filter_auto_disabled', False)
        self._filter_eval_count = data.get('_filter_eval_count', 0)
        # v9.5: восстановление factory-норм из JSON, else — fallback на текущие нормы
        if '_factory_feature_mean' in data and data['_factory_feature_mean'] is not None:
            self._factory_feature_mean = np.array(data['_factory_feature_mean'])
            self._factory_feature_std = np.array(data['_factory_feature_std'])
            self._factory_target_mean = np.array(data['_factory_target_mean'])
            self._factory_target_std = np.array(data['_factory_target_std'])
        else:
            self._factory_feature_mean = self.feature_mean.copy()
            self._factory_feature_std = self.feature_std.copy()
            self._factory_target_mean = self.target_mean.copy()
            self._factory_target_std = self.target_std.copy()
        return True

    @classmethod
    def load_default(cls):
        """Загрузка заводской модели, вшитой в код."""
        import json
        obj = cls()
        try:
            raw = zlib.decompress(base64.b64decode(_DEFAULT_MODEL_B64))
            data = json.loads(raw.decode('utf-8'))
            for attr in ['n_features', 'n_targets', 'hidden1', 'hidden2', 'hidden3',
                          'lr', 'max_grad_norm',
                          'is_trained', 'n_experiences',
                          'last_error_pct', 'last_error_linear_pct', '_train_steps']:
                if attr in data:
                    setattr(obj, attr, data[attr])
            for attr in ['W1', 'b1', 'W2', 'b2', 'W3', 'b3', 'W4', 'b4',
                          'feature_mean', 'feature_std', 'target_mean', 'target_std']:
                if attr in data:
                    setattr(obj, attr, np.array(data[attr]))
            obj.experience_configs = []
            obj.experience_targets = []
            obj._error_history = []
            obj.n_predictions = 0
            obj.n_experiences = 0  # v9.5: factory опыт выкинут — считаем с нуля
            # v9.3: сохраняем factory-нормы из загруженной модели
            obj._factory_feature_mean = obj.feature_mean.copy()
            obj._factory_feature_std = obj.feature_std.copy()
            obj._factory_target_mean = obj.target_mean.copy()
            obj._factory_target_std = obj.target_std.copy()
            # v9.6: инициализация счётчиков
            obj._n_accepted = 0
            obj._n_rejected = 0
            obj._n_rejected_no_targets = 0
            obj._norms_switched = False
            obj._filter_auto_disabled = False
            obj._filter_eval_count = 0
            print('[AI] Default model loaded (factory preset)')
            return obj
        except Exception as e:
            print(f'[AI] Failed to load default model: {e}')
            return obj
